package com.example.spatialapp.content

import android.util.Log
import com.pico.spatial.core.ecs.Entity
import com.pico.spatial.core.ecs.LoadType
import com.pico.spatial.core.ecs.TransformComponent
import com.pico.spatial.core.math.EulerAngles
import com.pico.spatial.core.math.Vector3
import com.pico.spatial.core.ecs.resource.AssetBundle
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * Generated by pico-spatial-mcp generate_environment_kotlin — BAKED textured-mesh environment.
 * Renders the texture (sharp, any scale, real geometry) by loading a spatialbundle-BAKED model.
 * FIRST bake it:  bake_textured_model(modelPath=<your apartment.glb>, outBundle=app/src/main/assets/apartment.bundle)
 * (Do NOT runtime-load the raw GLB — it renders black; and never `references=@x.glb@` in a USDA.)
 */
object MeshEnvironment {
    private const val TAG = "MeshEnvironment"
    private const val BUNDLE = "asset://apartment.bundle"
    private const val MODEL = "apartment"   // model name inside the baked bundle (the file stem)

    /** Call from SpatialView.initial (a coroutine):  MeshEnvironment.load { content.addEntity(it) }
     *  Pair with a box-collider rig for predictable Scene.rayCast alignment. Mesh shapes are queryable,
     *  but imported submesh local offsets/display scale must be applied to the collider entity. */
    suspend fun load(add: (Entity) -> Unit) {
        runCatching {
            val bundle = withContext(Dispatchers.IO) { AssetBundle.load(BUNDLE) }
            val e = Entity.loadSuspend(MODEL, bundle)   // the BAKED model -> renders textured
            withContext(Dispatchers.Main) {
                e.setName("MeshEnvironment")
                e.components.get(TransformComponent::class.java)?.setPosition(Vector3(0f, 0f, -2.5f))
                add(e)
                Log.i(TAG, "baked textured mesh attached")
            }
        }.onFailure { Log.e(TAG, "mesh env load failed: ${it.message}", it) }
    }
}

